const required = ['provider_type', 'supplier', 'invoice', 'customer', 'amounts', 'confidence', 'warnings'];
const first = (...values) => values.find((value) => value !== undefined && value !== null) ?? null;
const numberOrNull = (value) => { const number = Number(value); return value !== null && value !== '' && Number.isFinite(number) ? number : null; };
const addressText = (value) => value && typeof value === 'object' ? [value.street, value.number, value.floor, value.zip, value.city].filter(Boolean).join(', ') : first(value);

return items.map((item, index) => {
  const raw = item.json.output ?? item.json.text ?? item.json.response ?? '';
  const sourceFile = item.binary?.data?.fileName ?? `invoice-${index + 1}.pdf`;
  const safeSourceFile = sourceFile.replace(/[^a-zA-Z0-9._-]/g, '_');
  const stem = safeSourceFile.replace(/\.[^.]+$/, '') || `invoice-${index + 1}`;
  let parsed = null;
  const errors = [];

  try {
    const cleaned = typeof raw === 'string' ? raw.trim().replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\s*\`\`\`$/, '') : raw;
    parsed = typeof cleaned === 'string' ? JSON.parse(cleaned) : cleaned;
  } catch (error) {
    errors.push(`Invalid JSON returned by the model: ${error.message}`);
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    errors.push('The model output is not a JSON object.');
  } else {
    const source = parsed;
    const providerAliases = { electricity: 'edp', energy: 'edp', telecom: 'nos', telecommunications: 'nos', water: 'agua', água: 'agua' };
    let providerType = providerAliases[String(source.provider_type ?? '').toLowerCase()] ?? String(source.provider_type ?? '').toLowerCase();
    const supplierName = String(source.supplier?.name ?? '').toLowerCase();
    if (!['nos', 'edp', 'agua', 'unknown'].includes(providerType)) {
      providerType = supplierName.includes('edp') ? 'edp' : supplierName.includes('nos') ? 'nos' : 'unknown';
    }

    const period = source.invoice?.period ?? source.consumption?.electricity?.period ?? source.consumption?.water?.period ?? {};
    const amountSource = source.amounts ?? {};
    const electricityAmounts = amountSource.electricity ?? {};
    const warningSource = source.warnings ?? source.consumption?.warnings ?? [];
    const warnings = (Array.isArray(warningSource) ? warningSource : [warningSource]).map((warning) => typeof warning === 'string' ? warning : first(warning?.message, warning?.code, JSON.stringify(warning))).filter(Boolean);
    const confidenceSource = source.confidence;
    let confidence = numberOrNull(confidenceSource);
    if (confidence === null && confidenceSource && typeof confidenceSource === 'object') {
      confidence = numberOrNull(first(confidenceSource.extraction, confidenceSource.overall));
      if (confidence === null) {
        const scores = Object.values(confidenceSource).map(numberOrNull).filter((value) => value !== null);
        confidence = scores.length ? scores.reduce((sum, value) => sum + value, 0) / scores.length : null;
      }
    }

    const consumptionSource = source.consumption?.electricity ?? source.consumption?.water ?? source.consumption ?? {};
    const realReadings = consumptionSource.readings?.real ?? {};
    const total = numberOrNull(first(amountSource.total, source.invoice?.total_amount, source.payment?.total_amount, amountSource.total_before_taxes?.total));
    const tax = numberOrNull(first(amountSource.tax, amountSource.total_taxes_and_fees, electricityAmounts.taxes_fees?.total));
    const subtotal = numberOrNull(first(amountSource.subtotal, electricityAmounts.subtotal, total !== null && tax !== null ? total - tax : null));

    parsed = {
      provider_type: providerType || 'unknown',
      supplier: {
        name: first(source.supplier?.name),
        tax_id: first(source.supplier?.tax_id, source.supplier?.nif, source.supplier?.crc)
      },
      invoice: {
        number: first(source.invoice?.number),
        issue_date: first(source.invoice?.issue_date),
        due_date: first(source.invoice?.due_date, source.payment?.due_date),
        billing_period_start: first(source.invoice?.billing_period_start, period.start),
        billing_period_end: first(source.invoice?.billing_period_end, period.end)
      },
      customer: {
        name: first(source.customer?.name),
        tax_id: first(source.customer?.tax_id, source.customer?.nif),
        account_number: first(source.customer?.account_number, source.customer?.contract_code, source.customer?.customer_number),
        address: addressText(source.customer?.address)
      },
      amounts: { subtotal, tax, total, currency: first(amountSource.currency, source.invoice?.currency, 'EUR') },
      payment: {
        method: first(source.payment?.method),
        entity: first(source.payment?.entity, source.invoice?.reference?.entity),
        reference: first(source.payment?.reference, source.invoice?.reference?.identifier),
        iban: first(source.payment?.iban)
      },
      consumption: {
        value: numberOrNull(first(consumptionSource.value, realReadings.total, consumptionSource.total)),
        unit: first(consumptionSource.unit, providerType === 'edp' ? 'kWh' : providerType === 'agua' ? 'm3' : null),
        meter_or_cpe: first(consumptionSource.meter_or_cpe, source.customer?.cpe, source.customer?.meter, source.raw_fields?.cpe)
      },
      raw_fields: source.raw_fields && typeof source.raw_fields === 'object' ? source.raw_fields : {},
      confidence: confidence ?? 0,
      warnings
    };

    for (const field of required) if (!(field in parsed)) errors.push(`Missing required field: ${field}`);
    if (!['nos', 'edp', 'agua', 'unknown'].includes(parsed.provider_type)) errors.push('Invalid provider_type.');
    if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) errors.push('confidence must be between 0 and 1.');
    if (!Array.isArray(parsed.warnings)) errors.push('warnings must be an array.');
    if (parsed.amounts?.currency !== 'EUR') errors.push('amounts.currency must be EUR.');
    if (parsed.amounts?.total === null) errors.push('The total invoice amount could not be determined.');
  }

  const isValid = errors.length === 0;
  const payload = isValid ? parsed : { source_file: sourceFile, status: 'error', errors, normalized_output: parsed, raw_model_output: raw };
  const resultName = isValid ? `${stem}.json` : `${stem}.error.json`;
  const resultData = Buffer.from(JSON.stringify(payload, null, 2), 'utf8').toString('base64');

  return {
    json: { is_valid: isValid, source_file: sourceFile, safe_source_file: safeSourceFile, result_file: resultName, validation_errors: errors, invoice: isValid ? parsed : null },
    binary: { ...(item.binary ?? {}), result: { data: resultData, mimeType: 'application/json', fileName: resultName, fileExtension: 'json' } },
    pairedItem: { item: index }
  };
});

return items.map((item, index) => {
  const invoice = item.json.invoice;
  return {
    json: {
      'Processed At': new Date().toISOString(),
      'Source File': item.json.source_file,
      'Provider': invoice.provider_type,
      'Supplier': invoice.supplier?.name ?? null,
      'Invoice Number': invoice.invoice?.number ?? null,
      'Issue Date': invoice.invoice?.issue_date ?? null,
      'Payment Due Date': invoice.invoice?.due_date ?? null,
      'Customer Name': invoice.customer?.name ?? null,
      'Customer Tax ID': invoice.customer?.tax_id ?? null,
      'Customer Account': invoice.customer?.account_number ?? null,
      'Customer Address': invoice.customer?.address ?? null,
      'Payment Method': invoice.payment?.method ?? null,
      'Multibanco Entity': invoice.payment?.entity ?? null,
      'Multibanco Reference': invoice.payment?.reference ?? null,
      'IBAN': invoice.payment?.iban ?? null,
      'Amount': invoice.amounts?.total ?? null,
      'Currency': invoice.amounts?.currency ?? 'EUR',
      'Confidence': invoice.confidence ?? null,
      'Warnings': Array.isArray(invoice.warnings) ? invoice.warnings.join(' | ') : ''
    },
    binary: item.binary,
    pairedItem: { item: index }
  };
});

const seen = new Set();
const rows = [];
const config = $('Parse extraction config').first().json;
const providerLabels = config.provider_labels ?? {};
for (const item of items) {
  if (!item.json || !item.json['Source File']) continue;
  const provider = String(item.json.Provider ?? '').toLowerCase();
  item.json.Provider = providerLabels[provider] ?? provider;
  item.json.Currency = item.json.Currency ?? config.currency;
  const key = `${item.json['Source File']}|${item.json['Invoice Number'] ?? ''}`;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push({ json: item.json });
}
return rows;
